     <script>
       const filterButtons = [...document.querySelectorAll(".filter-chip")];
       const productCards = [...document.querySelectorAll(".product-card")];
       const statusMessage = document.querySelector(".status-message");

       let statusTimeoutId;

       function setStatus(message) {
         if (!statusMessage) {
           return;
         }

         statusMessage.textContent = message;
         statusMessage.classList.add("is-visible");

         window.clearTimeout(statusTimeoutId);
         statusTimeoutId = window.setTimeout(() => {
           statusMessage.classList.remove("is-visible");
         }, 2200);
       }

       filterButtons.forEach((button) => {
         button.addEventListener("click", () => {
           const { filter } = button.dataset;

           filterButtons.forEach((chip) => {
             chip.classList.toggle("is-active", chip === button);
             chip.setAttribute("aria-pressed", String(chip === button));
           });

           productCards.forEach((card) => {
             const matches = filter === "all" || card.dataset.category === filter;
             card.hidden = !matches;
           });

           const visibleCount = productCards.filter((card) => !card.hidden).length;
           const label = button.textContent?.trim() || "All";
           setStatus(`Showing ${visibleCount} featured product${visibleCount === 1 ? "" : "s"} in ${label}.`);
         });
       });

       document.querySelectorAll(".product-card button").forEach((button) => {
         button.addEventListener("click", () => {
           const productName = button.getAttribute("data-product-name");
           if (productName) {
             setStatus(`${productName} added to bag.`);
           }
         });
       });

       document.querySelector(".search-form")?.addEventListener("submit", (event) => {
         event.preventDefault();
         setStatus("Search preview only. Explore the featured and deals sections below.");
       });

       document.querySelector(".membership-form")?.addEventListener("submit", (event) => {
         event.preventDefault();
         const emailInput = document.querySelector("#email-address");
         if (emailInput instanceof HTMLInputElement && emailInput.reportValidity()) {
           setStatus(`Thanks for joining, ${emailInput.value}. Early access alerts are on the way.`);
           emailInput.value = "";
         }
       });

       filterButtons[0]?.setAttribute("aria-pressed", "true");
     </script>
   </body>
 </html>

